\title{The Hedging Hump and Placement-Structured Ceilings\\ for Interval Hints in Ordered Search}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
We study a searcher who probes the cells $1,\dots,n$ one at a time, in an order of their choosing, looking for a hidden target $J$ with a known prior. The searcher pays the number of probes. An oracle supplies an \emph{interval hint}, ``the target lies in the window $S$,'' and the searcher trusts it at a level $\alpha\in[0,1]$. We prove three groups of results.
\textbf{(I) The hedging hump.} Let $\Eopt(\alpha)$ be the Bayes-optimal expected cost at trust level $\alpha$. It is concave and piecewise linear: it is the lower envelope of $n!$ affine functions. For every strictly decreasing prior and every window whose conditional mean position differs from that of its complement, some intermediate trust $\alpha\in(0,1)$ makes the optimal search strictly more expensive than ignoring the hint. For the min-law prior of $J=\min(U_1,U_2)$, with $U_1,U_2$ independent and uniform on $\{1,\dots,M\}$, and a right-placed window of width $W\le M/3$, partial trust is strictly worse than no hint, than full distrust and than full trust. No hump exceeds the uniform level $(n+1)/2$.
\textbf{(II) Placement-structured ceilings.} With perfect trust, a window of width $W$ whose start lies $d$ cells from the right end costs exactly $(W+1)(6d-4W+1)/(6(2d-W))$ probes. Cost strictly decreases as the window moves right. Every placement has speedup at most $M/W=1/x$. Asymptotically the speedup is $k(2m-1)/(3m-2)$ for $M=kW$ and $d=mW$. This gives $1/x$ for right windows, about $2/(3x)$ for left and centered windows, and a right-to-left ratio tending to $3/2$.
\textbf{(III) The calibration gate.} For a calibrated signal the expected saving is at most $r(n-1)$, where $r$ is the firing rate. A hint that is uniform on its window when it fires satisfies $r\alpha\le W\min_{j\in S}p_j$. Under the min-law with a right window this gives $r\alpha\le W/M^2$ and $\alpha\cdot(\text{saving})<x$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Ordered search with a prior}
Let $J$ be a random target in $\{1,\dots,n\}$ with prior $p=(p_1,\dots,p_n)$. A search order is a permutation $\sigma$ of the cells. The searcher probes $\sigma(1),\sigma(2),\dots$ until the target is found. If the target is in cell $\sigma(i)$, the cost is $i$. For a nonnegative weight vector $q$ put
\[
\cost(q,\sigma)=\sum_{i=1}^n i\,q_{\sigma(i)},\qquad \opt(q)=\min_\sigma \cost(q,\sigma).
\]
By the rearrangement inequality, the minimum is attained by listing cells in non-increasing weight. When $p$ is non-increasing, the ascending scan is optimal.

\subsection{The two-number model}
Let $U_1,U_2$ be independent and uniform on $\{1,\dots,M\}$, and let $J=\min(U_1,U_2)$. Counting pairs gives the \emph{min-law}
\begin{equation}\label{eq:minlaw}
\Pr(J=i)=\frac{2(M-i)+1}{M^2},\qquad i=1,\dots,M.
\end{equation}
It is strictly decreasing. Its mean, which is also the optimal blind cost, is
\begin{equation}\label{eq:blind}
B(M)=\frac{(M+1)(2M+1)}{6M}\approx\frac M3 .
\end{equation}
For $M=512$, $B=171.17$; for $M=256$, $B=85.83$. The model abstracts the search for the smaller factor of a product of two numbers. Trial division searches from the left; Fermat's method, ``start at $\sqrt N$,'' commits to the extreme right of the range.

\subsection{Interval hints and trust}
An oracle names a window $S$, with prior mass $P(S)=\sum_{j\in S}p_j\in(0,1)$.

\begin{definition}[trust posterior]
For $\alpha\in\mathbb R$ let
\[
q_\alpha(j)=\begin{cases}\dfrac{\alpha}{P(S)}\,p_j,& j\in S,\\[2mm] \dfrac{1-\alpha}{1-P(S)}\,p_j,& j\notin S,\end{cases}
\qquad \Eopt(\alpha)=\opt(q_\alpha).
\]
\end{definition}

The posterior $q_\alpha$ is a probability vector for every $\alpha$ and is affine in $\alpha$. At the \emph{calibrated trust} $\alpha=P(S)$ it equals the prior, so $\Eopt(P(S))$ is the blind cost. The conditional mean positions are
\[
\muin=\frac{\sum_{j\in S}j\,p_j}{P(S)},\qquad \muout=\frac{\sum_{j\notin S}j\,p_j}{1-P(S)}.
\]

\subsection{Windows and placements}
For the min-law on $M$ cells, a window of width $W$ is a block of consecutive cells, and $x=W/M$ is its fraction. A \emph{right} window is $\{M-W+1,\dots,M\}$ and a \emph{left} window is $\{1,\dots,W\}$. In general a window at distance $d$ from the right end occupies cells $M-d+1,\dots,M-d+W$, with $W\le d\le M$. The \emph{speedup} of a strategy is $B(M)$ divided by its expected cost.

\section{The shape of the trust curve}

\begin{theorem}[concave piecewise-linear shape]\label{thm:concave}
For every prior $p$ and window $S$, $\alpha\mapsto\Eopt(\alpha)$ is concave on $\mathbb R$, and
\[
\Eopt(\alpha)=\min_\sigma\big[\alpha\,\cost(q_1,\sigma)+(1-\alpha)\,\cost(q_0,\sigma)\big].
\]
\end{theorem}
\begin{proof}
The cost of a fixed order is linear in the weights, so $\opt$ is a minimum of linear functions and hence concave. The map $\alpha\mapsto q_\alpha=\alpha q_1+(1-\alpha)q_0$ is affine.
\end{proof}

\begin{lemma}[forward plus backward]\label{lem:fb}
For any weight vector $q$ on $n$ cells, $\cost(q,\mathrm{id})+\cost(q,\mathrm{rev})=(n+1)\sum_j q_j$.
\end{lemma}
\begin{proof}
Cell $j$ is reached at step $j$ in one scan and at step $n+1-j$ in the other.
\end{proof}

\begin{theorem}[uniform ceiling]\label{thm:ceiling}
For every weight vector $q$, $\opt(q)\le\frac{n+1}{2}\sum_jq_j$. Hence $\Eopt(\alpha)\le(n+1)/2$ for every prior, window and trust level. The uniform vector attains the bound.
\end{theorem}
\begin{proof}
The minimum is at most the average of the two scans in Lemma~\ref{lem:fb}. For the uniform vector every order costs $(n+1)/2$.
\end{proof}

\begin{proposition}[uniform-given-hit hints reach the ceiling]
If a trusted window of width $W$ ($0<W<M$) gets uniform mass, $q(j)=\alpha/W$ on the window and $(1-\alpha)/(M-W)$ elsewhere, then at $\alpha=W/M$ the posterior is uniform. So $\opt=(M+1)/2$, and no trust level exceeds this value.
\end{proposition}

\section{The hedging hump}

\begin{lemma}[local rigidity]\label{lem:rigid}
Let $p$ be strictly decreasing and $0<P(S)<1$. On a neighbourhood of $\alpha=P(S)$, the posterior $q_\alpha$ is non-increasing in $j$, so the ascending scan is optimal.
\end{lemma}
\begin{proof}
At $\alpha=P(S)$ both scaling factors equal $1$. For each pair $i<j$ the inequalities $\frac{1-\alpha}{1-P(S)}p_j<\frac{\alpha}{P(S)}p_i$ and $\frac{\alpha}{P(S)}p_j<\frac{1-\alpha}{1-P(S)}p_i$ hold strictly, since $p_j<p_i$. They persist on a neighbourhood by continuity, because there are finitely many pairs.
\end{proof}

Along the ascending scan,
\begin{equation}\label{eq:committed}
\cost(q_\alpha,\mathrm{id})=\alpha\,\muin+(1-\alpha)\,\muout ,
\end{equation}
which is linear in $\alpha$ and equals the blind cost at $\alpha=P(S)$.

\begin{theorem}[Hedging Hump Theorem]\label{thm:hump}
Let $p$ be strictly decreasing, $0<P(S)<1$ and $\muin\neq\muout$. Then there is $\alpha\in(0,1)$ with $\Eopt(\alpha)>\opt(p)$.
\end{theorem}
\begin{proof}
On the neighbourhood of Lemma~\ref{lem:rigid}, $\Eopt(\alpha)-\opt(p)=(\alpha-P(S))(\muin-\muout)$. Choose $\alpha$ slightly above $P(S)$ if $\muin>\muout$ and slightly below otherwise.
\end{proof}

\begin{theorem}[Right-Window Hump Theorem]\label{thm:righthump}
Let $p$ be the min-law on $M$ cells and $S$ the right window of width $W$ with $0<W$ and $3W\le M$. There is $\alpha\in(0,1)$ with
\[
\Eopt(\alpha)>\max\{\opt(p),\Eopt(0),\Eopt(1)\}.
\]
\end{theorem}
\begin{proof}
We have $\muin\ge M-W+1>M-W\ge\muout$, so Theorem~\ref{thm:hump} applies. The ascending scan gives $\Eopt(0)\le\muout<\opt(p)$, because the blind cost is a proper mixture of $\muin$ and $\muout$. The descending scan gives $\Eopt(1)\le W$, and $W<B(M)$ because $6MW\le 2M^2<(M+1)(2M+1)$.
\end{proof}

