\section{Placement-structured ceilings}
Here $\alpha=1$, and the searcher scans the window in ascending order. This is optimal, because the conditioned min-law is still decreasing.

\begin{theorem}[Placement Law]\label{thm:placement}
A window of width $W\ge1$ at distance $d$ from the right end ($W\le d\le M$) costs
\[
E(d,W)=\frac{(W+1)(6d-4W+1)}{6(2d-W)} .
\]
\end{theorem}
\begin{proof}[Proof sketch]
Window cell $r=0,\dots,W-1$ has prior $(2d-1-2r)/M^2$. The window mass is $Z=W(2d-W)/M^2$, and the positional sum is
\[
N=\frac1{M^2}\Big[(2d-1)\tfrac{W(W+1)}2-\tfrac{2(W-1)W(W+1)}3\Big]=\frac{W(W+1)(6d-4W+1)}{6M^2}.
\]
Then $E=N/Z$.
\end{proof}

\begin{theorem}[right is cheapest]\label{thm:mono}
For $W\ge2$ and $d'<d$, $E(d',W)<E(d,W)$.
\end{theorem}
\begin{proof}
After cross-multiplication the sign of the difference is that of $-2(d-d')(W-1)<0$.
\end{proof}

\begin{theorem}[self-similarity]\label{thm:self}
Conditioned on the right window of width $W$, the min-law on $M$ cells is the min-law on $W$ cells. The right window has mass $W^2/M^2=x^2$ and cost $B(W)=(W+1)(2W+1)/(6W)$.
\end{theorem}

\begin{theorem}[universal ceiling]\label{thm:ceil}
For every placement, $B(M)/E(d,W)\le M/W=1/x$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:mono} it suffices to take $d=W$. The claim $B(M)/B(W)\le M/W$ is equivalent to $3MW(W-M)+(W^2-M^2)\le0$.
\end{proof}

\begin{theorem}[asymptotic placement law]\label{thm:asym}
For integers $1\le m\le k$, with $M=kW$ and $d=mW$, the speedup $B(kW)/E(mW,W)$ tends to $k(2m-1)/(3m-2)$ as $W\to\infty$.
\end{theorem}
\begin{proof}[Proof sketch]
Dividing by $W^2$ gives $\dfrac{(k+\frac1W)(2k+\frac1W)(2m-1)}{k(1+\frac1W)((6m-4)+\frac1W)}$, which tends to $\dfrac{k(2m-1)}{3m-2}$.
\end{proof}

\begin{corollary}
With $k=1/x$: a right window ($m=1$) tends to $1/x$; a left window ($m=k$) tends to $(2-x)/(x(3-2x))\to 2/(3x)$; a centered window tends to about $2/(3x)$. For $m\ge2$ the limit is strictly less than $k$. The right-to-left ratio $(3k-2)/(2k-1)$ tends to $3/2$.
\end{corollary}

