\subsection{Partial trust in a left window}
For a left window, the window-first ascending scan costs
\[
C(\alpha)=\alpha\frac{N_W}{P_W}+(1-\alpha)\frac{B(M)-N_W}{1-P_W},
\]
where $P_W=W(2M-W)/M^2$ and $N_W=\frac{W(W+1)}{M^2}\big(\frac{2M+1}2-\frac{2W+1}3\big)$.

\begin{theorem}[trust crossings]
Let $M=256$ and $\mathrm{sp}(\alpha)=B(M)/C(\alpha)$. For $x=1/8$, $\mathrm{sp}(0.995)<5.19<\mathrm{sp}(0.996)$, and $C$ is strictly decreasing, so the crossing is unique. For $x=1/64$, $\mathrm{sp}(0.836)<5.19<\mathrm{sp}(0.837)$.
\end{theorem}

As $M$ grows the crossings drift: for $x=1/64$ they are $0.8367,0.8344,0.8332$ at $M=256,512,1024$, approaching about $0.832$; for $x=1/8$ they are $0.9957,0.9935,0.9923$. The useful regime is narrow and near-certain.

\section{The calibration gate}

\begin{definition}[calibrated binary signal]
A signal fires with probability $r\in[0,1]$, giving posterior $q$, and otherwise gives $q'$. Here $q,q'\ge0$, $\sum_j q_j=1$, and
\begin{equation}\label{eq:split}
p_j=r\,q_j+(1-r)\,q'_j\quad\text{for all }j .
\end{equation}
Its expected saving is $\opt(p)-[r\opt(q)+(1-r)\opt(q')]$.
\end{definition}

\begin{theorem}[lightest-cell cap]\label{thm:cap}
If \eqref{eq:split} holds with $r\le1$ and $q'\ge0$, and $q_j=\alpha/W$ on a set $S$ of size $W$, then $r\alpha/W\le p_j$ for every $j\in S$.
\end{theorem}
\begin{proof}
$p_j=r\alpha/W+(1-r)q'_j\ge r\alpha/W$.
\end{proof}

\begin{theorem}[value is linear in the firing rate]\label{thm:value}
For any calibrated signal on $n$ cells with $r\ge0$, the expected saving is at most $r(n-1)$.
\end{theorem}
\begin{proof}
Let $\sigma$ be optimal for $q'$. Then $\opt(p)\le\cost(p,\sigma)=r\cost(q,\sigma)+(1-r)\opt(q')$, with $\cost(q,\sigma)\le n$ and $\opt(q)\ge1$.
\end{proof}

\begin{theorem}[calibration gate]\label{thm:gate}
Let $p$ be the min-law on $M$ cells and $S$ the right window of width $1\le W\le M$. For a calibrated uniform-given-hit signal on $S$ with $0\le r\le 1$ and $\alpha\ge0$,
\[
r\alpha\le\frac W{M^2},\qquad \alpha\cdot(\text{expected saving})<\frac WM=x.
\]
\end{theorem}
\begin{proof}
The lightest cell of $S$ is cell $M$, with prior $1/M^2$; apply Theorem~\ref{thm:cap}. Then Theorem~\ref{thm:value} gives $\alpha\cdot\text{saving}\le\alpha r(M-1)\le W(M-1)/M^2<W/M$.
\end{proof}

\begin{theorem}[calibrated capacity of the rightmost commitment]
The right window has prior mass $x^2$. So the calibrated trust of a ``start at the right end'' commitment vanishes quadratically in $x$.
\end{theorem}

For $M=512$ and $x=1/16$: $r\alpha\le1.22\times10^{-4}$, and the saving is below $1/16$ of a probe against a blind cost of $171.17$. For the left window the lightest cell has mass $961/512^2\approx3.67\times10^{-3}$, and the cap is $r\alpha\le0.117$. The gate is a right-placement phenomenon.

\section{Algorithms}
\begin{algorithm}[optimal ordered search]
Sort the cells by non-increasing weight and probe in that order; $O(n\log n)$.
\end{algorithm}
\begin{algorithm}[trust curve]
For each $\alpha$ on a grid, form $q_\alpha$ and sort. The exact breakpoints are the at most $|S|\,|S^c|$ solutions of $\frac{\alpha}{P(S)}p_i=\frac{1-\alpha}{1-P(S)}p_j$.
\end{algorithm}
\begin{algorithm}[gate test]
A uniform-given-hit signal with parameters $(r,\alpha)$ exists iff $r\alpha\le W\min_{j\in S}p_j$; then $q'_j=(p_j-rq_j)/(1-r)$.
\end{algorithm}

\section{Numerical verification}
For $M=5,\dots,8$, brute force over all $M!$ orders agrees with sorting; the worst gap is at the level of floating-point round-off. The placement law agrees exactly with direct summation for all $1\le W\le M<40$. Monte Carlo simulation over $40$ configurations gives a maximal standardized deviation of $|z|=2.34$. An early normalization error in the complement mass was exposed by a simulated mean at $z=-72$.

\section{Discussion}
\emph{Hedging is the expensive regime.} The trust curve is a concave tent that, for decreasing priors, rises above the blind level on one side of the calibrated point. A searcher who is unsure should either ignore a hint or commit to it.
\emph{Placement beats width.} Right windows are self-similar copies of the whole problem and reach the $1/x$ ceiling. Left and centered windows reach only about $2/(3x)$.
\emph{Honesty closes the right door.} A calibrated uniform hint on the right window is limited by the lightest cell, $1/M^2$, and its calibrated trust is $x^2$. ``Start at $\sqrt N$'' is a rightmost commitment with vanishing calibrated capacity.
\emph{Location versus identity.} An interval hint about the value of $J$ is symmetric in $U_1,U_2$, so it carries zero information about which number is the smaller. Yet it changes the optimal order. The two kinds of information are priced by orthogonal functionals.

\section{Future directions}
\begin{enumerate}
\item \emph{Exact hump height.} Conjecture: the continuum peak $\max_\alpha\Eopt/M$ for a right window equals $\frac13+c\,x(1-x)^2+O(x^2)$, and the hump is the cross term $\int\lambda_{\mathrm{in}}\lambda_{\mathrm{out}}$ in a level-set representation.
\item \emph{Rigidity radius.} With $\rho=\min_ip_i/p_{i+1}$, the ascending order should be optimal exactly when $\max(\lambda_{\mathrm{in}}/\lambda_{\mathrm{out}},\lambda_{\mathrm{out}}/\lambda_{\mathrm{in}})\le\rho$.
\item \emph{Polynomial priors.} For $J=\min(U_1,\dots,U_d)$: right ceiling $1/x$ and right/left ratio $(d+1)/d$.
\item \emph{Multi-signal hints.} Extend Theorem~\ref{thm:value} to $K$-outcome signals via a common reference order.
\end{enumerate}

\section{Conclusion}
The search for the smaller of two random numbers already shows three phenomena of hinted search. The cost of acting on a hint is concave in trust and peaks above the no-hint cost at partial trust. Placement determines value as much as width: the exact ceiling $1/x$ is reached by right windows and missed by a factor tending to $2/3$ elsewhere. Calibration ties a uniform hint's strength to its lightest cell, which closes off the most valuable placement to honest uniform hints.

