from __future__ import annotations
from fractions import Fraction


def blind_cost(M: int) -> Fraction:
    """Optimal blind cost under the min-law: (M+1)(2M+1)/(6M)."""
    return Fraction((M + 1) * (2 * M + 1), 6 * M)


def placement_cost(M: int, s: int, W: int) -> Fraction:
    """Exact perfect-trust cost of the window {s+1, ..., s+W}: (W+1)(6d-4W+1)/(6(2d-W)), d = M-s."""
    assert 1 <= W and s + W <= M
    d = M - s
    return Fraction((W + 1) * (6 * d - 4 * W + 1), 6 * (2 * d - W))


def placement_speedup(M: int, s: int, W: int) -> Fraction:
    return blind_cost(M) / placement_cost(M, s, W)


def asymptotic_speedup(k: int, m: int) -> Fraction:
    """Limit of the speedup for M = kW, d = mW as W -> infinity: k(2m-1)/(3m-2)."""
    return Fraction(k * (2 * m - 1), 3 * m - 2)


def best_placement(M: int, W: int) -> int:
    """Start index of the cheapest window: always the right end (cost strictly decreasing in s)."""
    return min(range(M - W + 1), key=lambda s: placement_cost(M, s, W))


if __name__ == "__main__":
    M, W = 256, 16
    for name, s in (("left", 0), ("centered", (M - W) // 2), ("right", M - W)):
        sp = placement_speedup(M, s, W)
        assert sp <= Fraction(M, W)
        print(f"{name:9s} speedup {float(sp):7.3f}  (ceiling {M // W})")
    assert best_placement(M, W) == M - W
    print("asymptotic right/left for k = 16:", float(asymptotic_speedup(16, 1) / asymptotic_speedup(16, 16)))
